import{_ as l,l as r,o as e,c as s,v as t,p as n,x as o,d as p,i as B,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"PAB 与溶剂残留","description":"","frontmatter":{"title":"PAB 与溶剂残留","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pab-solvent.md","filePath":"litho/pab-solvent.md","lastUpdated":1789023840000}'),P={name:"litho/pab-solvent.md"};function d(A,a,E,_,c,m){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="pab-与溶剂残留" tabindex="-1">PAB 与溶剂残留 <a class="header-anchor" href="#pab-与溶剂残留" aria-label="Permalink to &quot;PAB 与溶剂残留&quot;">​</a></h1><div class="epigraph"><p>前烘要赶的是溶剂，不是酸。残留溶剂当增塑剂：自由体积涨，同一 PEB 下酸走得更远，膜厚与 swing 也一起挪。</p><footer>—— 据 Mack 对软烤 / PAB 与残留溶剂的论述整理</footer></div><p><a href="/litho/resist-shelf-life">上一课</a>写了桶里和等待中的时间。缺口是涂完之后立刻、曝光之前那一步：post-apply bake（PAB，软烤）。主干轨道还没写到本补层的烘箱细节；<a href="/litho/peb-bake">PEB 温度</a>已经禁止把两个烘混成「热剂量」。本课钉 PAB 与溶剂残留。胶与底层怎样粘住，留给<a href="/litho/underlayer-adhesion">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>旋涂留下大量溶剂。PAB 把它降到可重复的残留水平，同时初步松弛应力、定膜厚。残留高：有效 \\(T_g\\) 低，\\(D\\) 大，LWR 核胖，回流窗口提前打开；残留低到过烘：膜致密、有时起皮、灵敏度掉、黏附变差。缺口是把溶剂分数写成 PEB 扩散系数的前置，而不是再讲一次催化时钟。</p><p>膜厚随溶剂离开而减薄，swing 工作点移动。剂量环锁不住这件事——薄膜课已经说过 swing 不是剂量环的对象；本课指出执行器是 PAB，不是扫描机。</p><h3 id="pab-peb" tabindex="-1">PAB ≠ PEB <a class="header-anchor" href="#pab-peb" aria-label="Permalink to &quot;PAB ≠ PEB&quot;">​</a></h3><p>PAB：无酸催化任务（CAR 上酸还没出生）。PEB：酸已经在，温度同时开增益与扩散。把 PAB 设成 PEB 温度「顺便省一步」，会在曝光前就把膜的自由体积和黏附做坏，且对 DNQ 与 CAR 都没有催化收益。</p><p><span class="marginnote">溶剂梯度沿 \\(z\\) 往往顶部先干、底部后干。底部增塑更久，footing 或黏附失败会像光学离焦。先查烘，再查焦。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>旋钮：热板温度、时间、是否真空、升降温。表征：称重或光谱残留、膜厚、折射率、\\(E_0\\)、\\(\\ell\\) 代理（LWR）、swing 曲线是否锁在目标厚。跨片均匀性与 PEB 热板同样进 CDU：PAB 指纹跟涂胶单元 ID 走。</p><p>与<a href="/litho/tg-free-volume">自由体积</a>联合：PAB 是产线控制自由体积的手段；树脂 \\(T_g\\) 是材料上限。只拧 PEB 去补 PAB 不足，等于用催化时钟去修增塑，LWR 与灵敏度一起透支。</p>',12)),(e(),n(h,null,{default:o(()=>[B(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPIN%5B%22%E6%97%8B%E6%B6%82%E6%B9%BF%E8%86%9C%22%5D%20--%3E%20PAB%5B%22PAB%20%E8%B5%B6%E6%BA%B6%E5%89%82%22%5D%0A%20%20PAB%20--%3E%20RES%5B%22%E6%AE%8B%E7%95%99%E6%BA%B6%E5%89%82%22%5D%0A%20%20RES%20--%3E%20FV%5B%22%E8%87%AA%E7%94%B1%E4%BD%93%E7%A7%AF%20%2F%20%E6%9C%89%E6%95%88%20Tg%22%5D%0A%20%20FV%20--%3E%20D%5B%22PEB%20%E7%9A%84%20D%22%5D%0A%20%20PAB%20--%3E%20THK%5B%22%E8%86%9C%E5%8E%9A%20%2F%20swing%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>溶剂分子占据自由体积并增塑链段。赶走它们，\\(D\\) 下降，酸在后烘里跳得少。赶得太狠，链段被冻在过密的玻璃里，PAG 运动也受阻，产酸效率微降。Mack 把软烤写成显影与 PEB 可重复性的前提：同一套 \\(R(m)\\) 参数默认某一残留；残留一漂，看起来像 \\(n\\) 和 \\(m_\\mathrm{th}\\) 变了。</p><p>环境湿度在 PAB 后仍可回吸，尤其薄胶。氮或受控湿度轨道是保 \\(T_g\\) 的一部分，不是奢侈。</p><p><span class="marginnote">上层涂层 / TARC 另有溶剂，PAB 曲线要按栈重做。不要把单层胶的软烤抄到三层栈。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写某胶的 90 °C / 60 s 当宇宙常数。轨道课会写热板硬件；本课只写溶剂物理。下一课黏附：溶剂走光之后，极性与底层表面能决定还贴不贴——过 PAB 可以让黏附变差，那是边界，不是本课把黏附理论写完。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PAB 赶溶剂、定厚与自由体积；PEB 才催化。</li><li>残留溶剂增塑，抬 PEB 的 \\(D\\) 与回流风险。</li><li>膜厚变化移动 swing；执行器是烘箱不是剂量环。</li><li>沿 \\(z\\) 的干燥梯度会扮离焦与 footing。</li><li>出处：Mack 对 soft bake / 残留溶剂。</li></ul>',8))])}const u=l(P,[["render",d]]);export{b as __pageData,u as default};
